def minimum_recolors(blocks, k):
    white_count = blocks[:k].count('W')
    min_recolors = white_count
    for i in range(k, len(blocks)):
        if blocks[i] == 'W':
            white_count += 1
        if blocks[i - k] == 'W':
            white_count -= 1
        min_recolors = min(min_recolors, white_count)
    return min_recolors

